export const RESEARCHED_RECIPES:Recipe[]=ROWS.trim().split('\n').map((line,i)=>{
 const [title,cats,pre,cook,raw,mode,url,reference]=line.split('|');
 if(!title||!cats||!raw||!mode||!url||!reference)throw Error('Invalid researched catalog row '+i);
 const ingredients:RecipeIngredient[]=raw.split(',').map(fragment=>{
  const [id,rawAmount]=fragment.split('/');if(!id||!rawAmount||!BY_ID.has(id))throw Error(`${title}: missing ingredient ${id}`);
  const unit:Unit=fluids.has(id)?'ml':units.has(id)&&Number(rawAmount)<=12?'pcs':'g';
  return {ingredientId:id,quantity:{amount:Number(rawAmount),unit},essential:true};
 });
 const special= SPECIAL[title];
 const steps:Recipe['steps']=special?special.map((body,j)=>({title:`مرحله ${j+1}`,body})):makeSteps(mode,ingredients,title);
 const poultry=ingredients.some(x=>['chicken','chicken_thigh','chicken_leg','chicken_mince','turkey','ground_turkey'].includes(x.ingredientId));
 const groundMeat=ingredients.some(x=>['ground_beef','ground_lamb'].includes(x.ingredientId));
 const seafood=ingredients.some(x=>['fish','white_fish','salmon','cod','shrimp','sardine'].includes(x.ingredientId));
 const last=steps[steps.length-1]!;
 if(poultry)last.safetyNote='مرغ و بوقلمون خام را تا دمای داخلی دست‌کم ۷۴ درجه سانتی‌گراد بپز و از دماسنج غذایی استفاده کن.';
 else if(groundMeat)last.safetyNote='گوشت چرخ‌کرده را تا دمای داخلی دست‌کم ۷۱ درجه سانتی‌گراد بپز.';
 else if(seafood)last.safetyNote='ماهی باید تا دمای داخلی حداقل ۶۳ درجه سانتی‌گراد پخته شود.';
 const isAdaptation=/adaptation|جایگزین|بدون الکل/i.test(reference+' '+title);
 return {id:`recipe-${String(i+173).padStart(3,'0')}`,title,
  description:`طرح تدوینی ${title} با ${ingredients.slice(0,3).map(x=>say(x.ingredientId)).join('، ')}؛ مقادیر برآوردی و نیازمند بازبینی آشپزی.`,
  categories:Array.from(new Set(cats.split('').map(c=>C[c]!).filter(Boolean))),
  servings:3,prepMinutes:Number(pre),cookMinutes:Number(cook),
  difficulty:Number(pre)+Number(cook)>=100?'medium':'easy',ingredients,steps,contentStatus:'draft',
  provenance:{kind:isAdaptation?'editorial':'source',url,sourceScope:isAdaptation?'adaptation':url.includes('tollbit.bbcgoodfood.com')||url.includes('20064-ghaza-irani')?'collection':'recipe',sourceTitle:reference}
 };
});
